import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.7He2WLS4.js";const u=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1772297611000}'),i={name:"faq.md"};function r(n,e,l,c,h,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-nectoproxy" tabindex="-1">What is NectoProxy? <a class="header-anchor" href="#what-is-nectoproxy" aria-label="Permalink to &quot;What is NectoProxy?&quot;">​</a></h3><p>NectoProxy is a powerful HTTP/HTTPS debugging proxy with a built-in Web UI. It sits between your browser (or any HTTP client) and the internet, capturing, inspecting, and optionally modifying all traffic that flows through it. It is designed for web developers, mobile developers, QA engineers, and security researchers who need to understand and manipulate network traffic.</p><h3 id="is-nectoproxy-free" tabindex="-1">Is NectoProxy free? <a class="header-anchor" href="#is-nectoproxy-free" aria-label="Permalink to &quot;Is NectoProxy free?&quot;">​</a></h3><p>Yes. NectoProxy is free and open source software released under the <a href="https://github.com/sitharaj88/nectoproxy/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT License</a>.</p><h3 id="what-license-does-nectoproxy-use" tabindex="-1">What license does NectoProxy use? <a class="header-anchor" href="#what-license-does-nectoproxy-use" aria-label="Permalink to &quot;What license does NectoProxy use?&quot;">​</a></h3><p>NectoProxy uses the <strong>MIT License</strong>, which is one of the most permissive open source licenses. You can use, modify, and distribute NectoProxy freely, including in commercial projects.</p><h3 id="can-i-use-nectoproxy-commercially" tabindex="-1">Can I use NectoProxy commercially? <a class="header-anchor" href="#can-i-use-nectoproxy-commercially" aria-label="Permalink to &quot;Can I use NectoProxy commercially?&quot;">​</a></h3><p>Yes. The MIT License permits commercial use without any restrictions or royalties. You can use NectoProxy in your development workflow, CI/CD pipelines, or any other commercial context.</p><h3 id="what-platforms-does-nectoproxy-support" tabindex="-1">What platforms does NectoProxy support? <a class="header-anchor" href="#what-platforms-does-nectoproxy-support" aria-label="Permalink to &quot;What platforms does NectoProxy support?&quot;">​</a></h3><p>NectoProxy runs on any platform that supports Node.js 20 or later:</p><table tabindex="0"><thead><tr><th>Platform</th><th style="text-align:center;">Supported</th></tr></thead><tbody><tr><td>macOS (Intel &amp; Apple Silicon)</td><td style="text-align:center;">Yes</td></tr><tr><td>Linux (x64, ARM64)</td><td style="text-align:center;">Yes</td></tr><tr><td>Windows (x64)</td><td style="text-align:center;">Yes</td></tr><tr><td>WSL (Windows Subsystem for Linux)</td><td style="text-align:center;">Yes</td></tr></tbody></table><h3 id="does-nectoproxy-support-http-2" tabindex="-1">Does NectoProxy support HTTP/2? <a class="header-anchor" href="#does-nectoproxy-support-http-2" aria-label="Permalink to &quot;Does NectoProxy support HTTP/2?&quot;">​</a></h3><p>NectoProxy currently operates as an HTTP/1.1 proxy. It can proxy traffic to and from HTTP/2 servers, but the connection between the client and NectoProxy uses HTTP/1.1. This is sufficient for debugging purposes as the request/response semantics are preserved.</p><hr><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="do-i-need-anything-besides-node-js" tabindex="-1">Do I need anything besides Node.js? <a class="header-anchor" href="#do-i-need-anything-besides-node-js" aria-label="Permalink to &quot;Do I need anything besides Node.js?&quot;">​</a></h3><p>No. NectoProxy is a self-contained npm package. The only prerequisite is <strong>Node.js 20 or later</strong>. All dependencies (including the Web UI) are bundled in the package.</p><h3 id="can-i-run-nectoproxy-without-installing-it-globally" tabindex="-1">Can I run NectoProxy without installing it globally? <a class="header-anchor" href="#can-i-run-nectoproxy-without-installing-it-globally" aria-label="Permalink to &quot;Can I run NectoProxy without installing it globally?&quot;">​</a></h3><p>Yes. You can use <code>npx</code> to run NectoProxy without installing it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h3 id="how-do-i-update-nectoproxy" tabindex="-1">How do I update NectoProxy? <a class="header-anchor" href="#how-do-i-update-nectoproxy" aria-label="Permalink to &quot;How do I update NectoProxy?&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span></span></code></pre></div><p>Or reinstall the latest version:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy@latest</span></span></code></pre></div><h3 id="how-do-i-uninstall-nectoproxy" tabindex="-1">How do I uninstall NectoProxy? <a class="header-anchor" href="#how-do-i-uninstall-nectoproxy" aria-label="Permalink to &quot;How do I uninstall NectoProxy?&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remove the npm package</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optionally remove the data directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Removing the <code>~/.nectoproxy/</code> directory deletes all captured traffic, rules, settings, and certificates. Back up first if you need to preserve any data.</p></div><h3 id="what-is-the-minimum-node-js-version" tabindex="-1">What is the minimum Node.js version? <a class="header-anchor" href="#what-is-the-minimum-node-js-version" aria-label="Permalink to &quot;What is the minimum Node.js version?&quot;">​</a></h3><p>NectoProxy requires <strong>Node.js 20.0.0 or later</strong>. Check your version with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><hr><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><h3 id="is-installing-the-ca-certificate-safe" tabindex="-1">Is installing the CA certificate safe? <a class="header-anchor" href="#is-installing-the-ca-certificate-safe" aria-label="Permalink to &quot;Is installing the CA certificate safe?&quot;">​</a></h3><p>Installing the NectoProxy CA certificate tells your system to trust certificates issued by NectoProxy. This is safe <strong>as long as:</strong></p><ol><li>You generated the CA yourself by running NectoProxy on your own machine.</li><li>No one else has access to your <code>~/.nectoproxy/certs/ca.key</code> file.</li><li>You remove the CA certificate when you are done using NectoProxy.</li></ol><p>The CA private key never leaves your machine and is not shared over the network.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Never install a CA certificate provided by someone else unless you fully trust them. A malicious CA certificate would allow the holder to intercept all your HTTPS traffic.</p></div><h3 id="will-nectoproxy-intercept-all-my-traffic" tabindex="-1">Will NectoProxy intercept ALL my traffic? <a class="header-anchor" href="#will-nectoproxy-intercept-all-my-traffic" aria-label="Permalink to &quot;Will NectoProxy intercept ALL my traffic?&quot;">​</a></h3><p>NectoProxy only intercepts traffic that is explicitly routed through it. It does not change your system&#39;s default network configuration. Only applications configured to use <code>localhost:8888</code> as their proxy (either manually or via system proxy settings) will have their traffic captured.</p><p>If you configure your <strong>system proxy</strong> settings to point to NectoProxy, then all applications that respect system proxy settings will route through it.</p><h3 id="can-others-on-my-network-see-my-traffic" tabindex="-1">Can others on my network see my traffic? <a class="header-anchor" href="#can-others-on-my-network-see-my-traffic" aria-label="Permalink to &quot;Can others on my network see my traffic?&quot;">​</a></h3><p>By default, NectoProxy binds to <code>0.0.0.0</code> (all interfaces), which means devices on your local network can connect. Anyone on your local network can:</p><ul><li>Route their traffic through your proxy</li><li>View the Web UI and see captured traffic</li></ul><p>To restrict access to only your local machine, start with <code>--host 127.0.0.1</code>. Only use the default on trusted networks.</p><h3 id="how-do-i-remove-the-ca-certificate" tabindex="-1">How do I remove the CA certificate? <a class="header-anchor" href="#how-do-i-remove-the-ca-certificate" aria-label="Permalink to &quot;How do I remove the CA certificate?&quot;">​</a></h3><p><strong>macOS:</strong> Open Keychain Access, find &quot;NectoProxy CA&quot;, right-click, and delete.</p><p><strong>Windows:</strong> Open Certificate Manager (<code>certmgr.msc</code>), go to Trusted Root Certification Authorities, find &quot;NectoProxy CA&quot;, and delete.</p><p><strong>Linux:</strong> Remove the certificate file and update the store:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/share/ca-certificates/nectoproxy-ca.crt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-ca-certificates</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fresh</span></span></code></pre></div><p><strong>Firefox:</strong> Settings &gt; Privacy &amp; Security &gt; Certificates &gt; View Certificates &gt; Authorities &gt; find NectoProxy CA &gt; Delete.</p><h3 id="can-i-use-nectoproxy-on-a-shared-network" tabindex="-1">Can I use NectoProxy on a shared network? <a class="header-anchor" href="#can-i-use-nectoproxy-on-a-shared-network" aria-label="Permalink to &quot;Can I use NectoProxy on a shared network?&quot;">​</a></h3><p>Yes, but on shared or untrusted networks, restrict to localhost with <code>--host 127.0.0.1</code>.</p><hr><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="can-nectoproxy-capture-mobile-traffic" tabindex="-1">Can NectoProxy capture mobile traffic? <a class="header-anchor" href="#can-nectoproxy-capture-mobile-traffic" aria-label="Permalink to &quot;Can NectoProxy capture mobile traffic?&quot;">​</a></h3><p>Yes. NectoProxy listens on all interfaces by default, so just run <code>nectoproxy start</code>, configure your phone&#39;s Wi-Fi proxy settings to point to your computer&#39;s IP address (shown at startup) and port 8888, and install the CA certificate on the phone. See the <a href="./guides/debugging-mobile.html">Debugging Mobile Apps</a> tutorial for detailed instructions.</p><h3 id="does-nectoproxy-support-websockets" tabindex="-1">Does NectoProxy support WebSockets? <a class="header-anchor" href="#does-nectoproxy-support-websockets" aria-label="Permalink to &quot;Does NectoProxy support WebSockets?&quot;">​</a></h3><p>Yes. NectoProxy intercepts WebSocket connections (both <code>ws://</code> and <code>wss://</code>) and captures individual frames, including direction, opcode, data, and timestamps. WebSocket entries appear in the traffic list with protocol WS or WSS. See the <a href="./guides/debugging-websockets.html">Debugging WebSockets</a> tutorial.</p><h3 id="can-i-mock-api-responses" tabindex="-1">Can I mock API responses? <a class="header-anchor" href="#can-i-mock-api-responses" aria-label="Permalink to &quot;Can I mock API responses?&quot;">​</a></h3><p>Yes. NectoProxy&#39;s Rules engine supports Mock rules that return custom responses without forwarding the request to the real server. You can specify status codes, headers, body content, and even add delays. See the <a href="./guides/mocking-apis.html">Mocking APIs</a> tutorial.</p><h3 id="can-i-export-and-import-traffic" tabindex="-1">Can I export and import traffic? <a class="header-anchor" href="#can-i-export-and-import-traffic" aria-label="Permalink to &quot;Can I export and import traffic?&quot;">​</a></h3><p>Yes. NectoProxy supports exporting traffic as HAR (HTTP Archive) files and importing HAR files from other tools including Chrome DevTools, Firefox, Charles Proxy, and Fiddler. See the <a href="./guides/exporting-traffic.html">Exporting Traffic</a> tutorial.</p><h3 id="does-nectoproxy-work-with-grpc" tabindex="-1">Does NectoProxy work with gRPC? <a class="header-anchor" href="#does-nectoproxy-work-with-grpc" aria-label="Permalink to &quot;Does NectoProxy work with gRPC?&quot;">​</a></h3><p>NectoProxy can capture gRPC traffic that runs over HTTP/2. The Web UI includes a gRPC viewer that can decode and display gRPC messages. However, since NectoProxy operates as an HTTP/1.1 proxy, some gRPC features that require full HTTP/2 support (like bidirectional streaming) may not work through the proxy.</p><h3 id="can-i-use-nectoproxy-with-docker" tabindex="-1">Can I use NectoProxy with Docker? <a class="header-anchor" href="#can-i-use-nectoproxy-with-docker" aria-label="Permalink to &quot;Can I use NectoProxy with Docker?&quot;">​</a></h3><p>Yes. You can run NectoProxy inside a Docker container or use it to proxy traffic from Docker containers. To proxy traffic from containers, configure the container&#39;s HTTP proxy environment variables to point to NectoProxy on the host:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HTTP_PROXY=http://host.docker.internal:8888</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">           -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HTTPS_PROXY=http://host.docker.internal:8888</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">           your-image</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>host.docker.internal</code> resolves to the host machine&#39;s IP from inside a Docker container on Docker Desktop (macOS and Windows). On Linux, use <code>--network host</code> or the host&#39;s actual IP address.</p></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="why-is-no-traffic-appearing" tabindex="-1">Why is no traffic appearing? <a class="header-anchor" href="#why-is-no-traffic-appearing" aria-label="Permalink to &quot;Why is no traffic appearing?&quot;">​</a></h3><p>The most common causes are:</p><ol><li>Your browser is not configured to use the proxy (check proxy settings).</li><li>Recording is paused (check the record button in the header).</li><li>You are viewing a different session.</li><li>The proxy port is wrong.</li></ol><p>See <a href="./troubleshooting/common-issues.html">Common Issues</a> for detailed solutions.</p><h3 id="why-is-https-showing-security-errors" tabindex="-1">Why is HTTPS showing security errors? <a class="header-anchor" href="#why-is-https-showing-security-errors" aria-label="Permalink to &quot;Why is HTTPS showing security errors?&quot;">​</a></h3><p>The NectoProxy CA certificate is not installed or not trusted. Install it using:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span></code></pre></div><p>See <a href="./troubleshooting/certificate-errors.html">Certificate Errors</a> for platform-specific instructions.</p><h3 id="where-are-the-logs" tabindex="-1">Where are the logs? <a class="header-anchor" href="#where-are-the-logs" aria-label="Permalink to &quot;Where are the logs?&quot;">​</a></h3><p>NectoProxy writes logs to the terminal (stdout/stderr) where it was started. There is no separate log file by default. Error messages, proxy events, and startup information are all printed to the console.</p><h3 id="how-much-disk-space-does-nectoproxy-use" tabindex="-1">How much disk space does NectoProxy use? <a class="header-anchor" href="#how-much-disk-space-does-nectoproxy-use" aria-label="Permalink to &quot;How much disk space does NectoProxy use?&quot;">​</a></h3><p>Disk usage depends on how much traffic you capture. The database starts at a few kilobytes and grows as traffic is recorded. A session with a few hundred requests and small payloads typically uses 5-50 MB. Heavy usage with large response bodies can grow to hundreds of megabytes or more. See the <a href="./configuration/storage.html">Storage</a> page for management tips.</p><h3 id="can-i-run-nectoproxy-on-a-server" tabindex="-1">Can I run NectoProxy on a server? <a class="header-anchor" href="#can-i-run-nectoproxy-on-a-server" aria-label="Permalink to &quot;Can I run NectoProxy on a server?&quot;">​</a></h3><p>Yes. NectoProxy can run on a headless server. Start it with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span></span></code></pre></div><p>Access the Web UI from any browser using the server&#39;s IP address and UI port (default 8889). Make sure the appropriate ports are open in your server&#39;s firewall.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Running NectoProxy on a server accessible from the internet is not recommended without additional security measures (VPN, SSH tunnel, reverse proxy with authentication), as anyone who can reach it can view and manipulate traffic.</p></div>`,89)])])}const y=t(i,[["render",r]]);export{u as __pageData,y as default};
